        [MenuItem("Tow Trouble/Capture Open World Contract Photos")]
        public static void CaptureMapPhotos()=>CaptureMapPhotosWhere(_=>true);
        private static void CaptureMapPhotosWhere(Func<Vector3,bool> include)
        {
            // Existing maps retain their image GUIDs and never need a scene save for photography.
            if(RecoveryPhotoAuthoring.HasStableBindings())
            {RecoveryPhotoAuthoring.CaptureWhere((site,index)=>include(site.Position));return;}
            var scene=SceneManager.GetActiveScene();if(EditorApplication.isPlaying||scene.path!=ScenePath)throw new InvalidOperationException("Open map in Edit Mode.");var world=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<RecoveryWorld>()).Single();var hud=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<RecoveryHud>()).Single();var parent=new GameObject("Temporary static photo poses").transform;
            var cameraGo=new GameObject("Static contract camera");cameraGo.transform.SetParent(parent,false);var camera=cameraGo.AddComponent<Camera>();var cameraData=cameraGo.AddComponent<UnityEngine.Rendering.Universal.UniversalAdditionalCameraData>();cameraData.requiresDepthTexture=true;cameraData.requiresColorTexture=true;cameraData.renderPostProcessing=true;cameraData.antialiasing=UnityEngine.Rendering.Universal.AntialiasingMode.SubpixelMorphologicalAntiAliasing;camera.enabled=false;camera.farClipPlane=2300;camera.nearClipPlane=.2f;camera.fieldOfView=52;var rt=new RenderTexture(720,400,24);var pixels=new Texture2D(720,400,TextureFormat.RGB24,false);camera.targetTexture=rt;var images=new Texture2D[24];
            try{for(int i=0;i<world.Map.Sites.Length;i++){var site=world.Map.Sites[i];if(!include(site.Position)){images[i]=AssetDatabase.LoadAssetAtPath<Texture2D>(Root+"/Photos/"+site.Id+".png");continue;}world.Casualty.SetPaint(site.TargetPaint);var car=UiSkinAuthoring.PreviewVehicle(world.Casualty,site.TargetModel,parent,site.Position-Vector3.up*site.Depth);car.transform.rotation=Quaternion.Euler(site.Pitch,site.Heading,site.Roll);PoseSituationPhoto(car,world.Casualty,site);camera.transform.position=site.Position+new Vector3(15,8,-17);var focus=site.Position+Vector3.up*1.0f;if(Physics.Linecast(focus,camera.transform.position,out var obstruction,1<<8,QueryTriggerInteraction.Ignore))camera.transform.position=obstruction.point+obstruction.normal*.7f;var blockers=UnityEngine.Object.FindFirstObjectByType<Terrain>().transform.parent.GetComponentsInChildren<Renderer>().Where(r=>r.enabled&&r.gameObject.activeInHierarchy&&!r.transform.IsChildOf(parent)&&r.bounds.size.y>2).ToArray();float best=float.MaxValue;Vector3 bestPosition=camera.transform.position;for(int view=0;view<12;view++){float angle=view*30*Mathf.Deg2Rad;var candidate=site.Position+new Vector3(Mathf.Cos(angle)*14,7,Mathf.Sin(angle)*14);var terrain=UnityEngine.Object.FindFirstObjectByType<Terrain>();candidate.y=Mathf.Max(candidate.y,terrain.SampleHeight(candidate)+terrain.transform.position.y+3);var ray=new Ray(candidate,(focus-candidate).normalized);float length=Vector3.Distance(candidate,focus);float score=Physics.Linecast(focus,candidate,out _,1<<8,QueryTriggerInteraction.Ignore)?100:0;foreach(var r in blockers)if(r.bounds.IntersectRay(ray,out float distance)&&distance<length-2)score++;score+=view*.001f;if(score<best){best=score;bestPosition=candidate;}}camera.transform.position=Vector3.Lerp(focus,bestPosition,.72f);if(site.Kind==RecoverySituationKind.EngineFailure||site.Kind==RecoverySituationKind.Ditch||site.Kind==RecoverySituationKind.Embankment)camera.transform.position=site.Position+Quaternion.Euler(0,site.Heading,0)*new Vector3(-7,5,8);if(site.Id!="R01"&&GameObject.Find("Broad recovery ground zones")!=null&&site.Kind!=RecoverySituationKind.Water&&site.Kind!=RecoverySituationKind.EngineFailure&&site.Kind!=RecoverySituationKind.Rocks)camera.transform.position=site.Position+Quaternion.Euler(0,site.Heading,0)*new Vector3(-19,19,24);if(RoadsideRecovery(site)){camera.transform.position=site.Position+site.ExitDirection*8+Vector3.Cross(Vector3.up,site.ExitDirection)*8+Vector3.up*15;var ground=UnityEngine.Object.FindFirstObjectByType<Terrain>();var cp=camera.transform.position;cp.y=Mathf.Max(cp.y,ground.SampleHeight(cp)+ground.transform.position.y+3);camera.transform.position=cp;}camera.transform.LookAt(focus);PoseSituationSmoke(car,site,camera);camera.Render();var old=RenderTexture.active;RenderTexture.active=rt;pixels.ReadPixels(new Rect(0,0,720,400),0,0);pixels.Apply();RenderTexture.active=old;string path=Root+"/Photos/"+site.Id+".png";File.WriteAllBytes(path,pixels.EncodeToPNG());AssetDatabase.ImportAsset(path);var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.mipmapEnabled=false;importer.maxTextureSize=1024;importer.SaveAndReimport();images[i]=AssetDatabase.LoadAssetAtPath<Texture2D>(path);UnityEngine.Object.DestroyImmediate(car);}}
            finally{world.Casualty.SetPaint(0);UnityEngine.Object.DestroyImmediate(parent.gameObject);UnityEngine.Object.DestroyImmediate(pixels);rt.Release();UnityEngine.Object.DestroyImmediate(rt);}
